async function tkPastePin(key){ let p = null; const cats = (myCityListData && myCityListData.categories) || {}; Object.keys(cats).forEach(function(k){ ((cats[k] || {}).places || []).forEach(function(q){ if (q && plSugKey(q) === key) p = q; }); }); if (!p){ showToast('Place not found'); return; } let text = ''; try{ text = await navigator.clipboard.readText(); }catch(e){ showToast('Could not read the clipboard — in Google Maps tap Share → copy link, then tap again'); return; } const r = tkPasteParse(text); if (!r){ showToast('No Google Maps link or coordinates in the clipboard'); return; } const cell = tkFileLocOf(p); if (cell && !tkIsCellRow(p) && plKm(cell, r) > 50){ showToast('That link is ' + Math.round(plKm(cell, r)) + ' km from this place’s file spot — check it'); return; } const prev = plSuggestCache[key]; p.geo = { lat: +(+r.lat).toFixed(5), lng: +(+r.lng).toFixed(5), source: 'user_paste', via: 'paste' }; delete p.openId; if (r.url && r.url !== p.url) p.url2 = r.url; delete plSuggestCache[key]; try{ if (!(p.area || '').trim()){ const a = await mpData.geo.area(cityListCityId, p.geo.lat, p.geo.lng); if (a && !isCityOrCountry(a)) p.area = a; } }catch(e){ mpSwallow(e, 'area'); } try{ await saveMyCityList(); }catch(e){ mpSwallow(e, 'paste-pin'); delete p.geo; if (prev !== undefined) plSuggestCache[key] = prev; showToast('Could not save'); return; } tkUndoLast = { city: cityListCityId, items: [{ p: p, sg: prev === undefined ? undefined : prev }], at: Date.now(), tier: 'paste' }; showToast(r.approx ? 'Pinned from a list link (approximate ≈) — check it on the map' : 'Pinned from your link ✓'); try{ logTiming('PASTE PIN · ' + cityListCityId + ' · 1 pins · source user_paste via paste' + (r.approx ? ' · approximate cell' : '') + ' · your account only'); }catch(_){} renderPlacesMine(); try{ if (document.getElementById('tkConfirmList')) tkConfirmRender(false); else if (document.getElementById('tkUnpinnedBody')) tkUnpinnedOpen(); }catch(_){} } /* r86-8 v1.1: القائمة المفتوحة تُحدَّث في مكانها — الصف يخرج */ /* الدبوس في حسابه وحده · بلا هوية مشتركة · Undo في الصندوق */
function tkPastePinAt(catId, index){ const p = (((myCityListData || {}).categories || {})[catId] || { places: [] }).places[index]; if (!p) return; return tkPastePin(plSugKey(p)); }
/* ── الصندوق: سطر الحالة وأزراره (يُحقن في plUnsortedPanelHtml) ── */
function tkSortBoxHtml(){ const s = tkSortState[cityListCityId]; const strong = tkStrongList().length; const banned = tkBannedList().length; let h = '';
  if (s && s.status === 'running') h += '<div class="dim" id="tkSortLine" style="font-size:11.5px; margin:4px 0;">' + escapeHtml(s.progress || 'Finding pins…') + '</div>';
  else if (s && s.report){ const r = s.report; h += '<div class="dim" style="font-size:11.5px; margin:4px 0;">Auto-sort: ' + r.sorted + ' moved to their categories' + (r.upgraded ? ' · ' + r.upgraded + ' older place' + (r.upgraded === 1 ? '' : 's') + ' with a long link checked' : '') + (r.heldBySection ? ' · ' + r.heldBySection + ' kept here by the list’s section' : '') + (r.possible ? ' · ' + r.possible + ' need your pick' : '') + (r.notFound ? ' · ' + r.notFound + ' not found' : '') + (r.err ? ' · <span style="color:#ffb4a2;">' + escapeHtml(r.err) + '</span>' : '') + '</div>'; }
  const likelyN = tkLikelyList().length, fileN = tkFileList().length, sugN = tkPickList('suggested').length, posN = tkPickList('possible').length; const chip = function(fn, label, n, hint, on){ return '<div class="chiprow" style="margin:4px 0;"><button type="button" class="chip' + (on ? ' on' : '') + '" onclick="tkTierOpen(\'' + fn + '\')">' + label + ' ' + n + '</button><span class="dim" style="font-size:11px;">' + hint + '</span></div>'; }; /* r86-8 (كلمة المالك ١١:٤٤): شريحة لكل درجة بعددها الصادق */
  if (strong) h += chip('strong', '✓ Strong', strong, 'exact name within ' + TK_STRONG_M + ' m of Google’s spot — confirm in one tap', true);
  if (likelyN) h += chip('likely', '~ Likely', likelyN, 'name contains · the only one with this name · by address · large area — check the ↔ names');
  if (fileN) h += chip('file', '📍 Google spot', fileN, 'not in our map data — pinned from your file, your account only');
  if (sugN) h += chip('suggested', '◦ Single suggestion', sugN, 'one close name — tap it to accept');
  if (posN) h += chip('possible', '≈ Look-alikes', posN, 'several names — tap the right one');
  const unpN = tkUnpinnedList().length; if (unpN) h += '<div class="chiprow" style="margin:4px 0;"><button type="button" class="chip" onclick="tkUnpinnedOpen()">📋 Unpinned · ' + unpN + '</button><span class="dim" style="font-size:11px;">everything still without a pin — one flat list, save it as a file</span></div>'; /* r86-8 (كلمة المالك ١١:٤٤ البند ٣) */
  if (tkUndoLast && tkUndoLast.city === cityListCityId) h += '<div class="chiprow" style="margin:4px 0;"><button type="button" class="chip" onclick="tkUndoConfirm()">↶ Undo last confirm (' + tkUndoLast.items.length + ')</button></div>';
  if (tkRemovedLast && tkRemovedLast.city === cityListCityId && tkRemovedLast.items.length) h += '<div class="chiprow" style="margin:4px 0;"><button type="button" class="chip" onclick="tkRestoreRemoved()">↶ Restore ' + tkRemovedLast.items.length + ' removed</button><span class="dim" style="font-size:11px;">the ones you × in a list — back where they were</span></div>'; /* r86-8 v1.1 (كلمة المالك ١٣:١٠) */
  const approxN = tkApproxList().length; if (approxN) h += '<div class="dim" style="font-size:11px; margin:4px 0;">≈ ' + approxN + ' place' + (approxN === 1 ? ' has' : 's have') + ' only a list link (approximate spot) and no match in our data — pick ' + (approxN === 1 ? 'it' : 'them') + ' on the map</div>'; /* r86-6: الخلية التقريبية لا تُثبَّت جماعيًّا ولا تُرسم */
  if (banned) h += '<div class="chiprow" style="margin:4px 0;"><button type="button" class="chip" onclick="tkRemoveBanned()">Remove ' + banned + ' outside the guidelines</button><span class="dim" style="font-size:11px;">bars · nightlife · alcohol · hookah · gambling</span></div>';
  const lastImp = (typeof tkLast === 'function' && currentUser) ? tkLast() : null; if (lastImp && !lastImp.undone && !(typeof tkResumeLoad === 'function' && tkResumeLoad())){ const when = new Date(lastImp.at).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }); h += '<div class="chiprow" style="margin:4px 0;"><button type="button" class="chip" onclick="tkUndoFromBox()">↶ Undo last import · ' + escapeHtml(when) + ' · ' + lastImp.added + ' place' + (lastImp.added === 1 ? '' : 's') + '</button><span class="dim" style="font-size:11px;">last import only · keeps what you worked on</span></div>'; } /* r86-3 (البند ٤): التراجع من مكانه — بلا درج ولا Import */
  const dups = tkDupList().length; if (dups) h += '<div class="chiprow" style="margin:4px 0;"><button type="button" class="chip" onclick="tkRemoveDups()">Remove ' + dups + ' already pinned</button><span class="dim" style="font-size:11px;">the same place' + (dups === 1 ? '' : 's') + ' you already have on the map</span></div>'; /* r86 (البند ٨) */
  const wR = (typeof tkWaitingReady === 'function') ? tkWaitingReady() : []; const wN = wR.length; if (wN){ const byC = {}; wR.forEach(function(x){ byC[x.country] = (byC[x.country] || 0) + 1; }); h += '<div class="chiprow" style="margin:4px 0; flex-wrap:wrap; overflow:visible;"><button type="button" class="chip" style="white-space:normal; text-align:left; line-height:1.3; flex:0 1 auto; max-width:100%;" onclick="tkOpenImport()">' + wN + ' place' + (wN === 1 ? '' : 's') + ' waiting for their city (' + escapeHtml(Object.keys(byC).map(function(k){ return k + ' ' + byC[k]; }).join(' · ')) + ') · Place them now</button></div>'; } /* r86-2: بالدول */ /* r86 (IM-X3) */
  return h; }
function tkMiniPanelHtml(){ if (!currentUser || !myCityListData || myCityListLoadedFor !== cityListCityId) return ''; if (tkSortNeeded()) tkSortKick(); const s = tkSortState[cityListCityId]; const show = (s && s.status === 'running') || tkAllList().length || tkPickList().length || (tkRemovedLast && tkRemovedLast.city === cityListCityId) || tkDupList().length || (tkUndoLast && tkUndoLast.city === cityListCityId) || ((typeof tkWaitingReady === 'function') ? tkWaitingReady().length : 0); if (!show) return ''; return '<div class="pl-ownerpanel" id="plUnsortedMini"><b>📍 Pins to confirm</b>' + tkSortBoxHtml() + '</div>'; } /* r86: لا صندوق — لكن مترقٍّ خارج الصندوق يستحق Confirm all strong، أو Undo/تكرارات باقية */
function tkPlaceBadges(p){ let h = ''; if (!(p.geo && typeof p.geo.lat === 'number') && p.hold !== 'guidelines' && !p.dup){ const k = plSugKey(p); if (k in plSuggestCache){ const sg = plSuggestCache[k]; if (!sg) h += ' <span class="dim" style="font-size:11px;" title="' + attrStr('Not in our map data — ' + (tkNotFoundWhy[k] || 'pin it by hand from the map')) + '">· not found' + (tkNotFoundWhy[k] ? ' · ' + escapeHtml(tkNotFoundWhy[k].replace(/^nearest look-alike: /, '≈ ').replace(/^no candidate with a similar name.*/, 'no look-alike').replace(/ · also tried.*$/, '')) : '') + (tkIsCellRow(p) ? ' · ≈ list link' : '') + '</span>'; else if (sg.strong) h += ' <span style="font-size:11px; font-weight:700; color:#3f8f4b;" title="' + (sg.known ? 'Pinned before on our map (shared identity) — Review & pin pins it' : 'Exact name within 100 m of Google’s spot — Review & pin pins it') + '">· strong' + (sg.known ? ' · pinned before' : '') + '</span>'; else if (sg.likely) h += ' <span style="font-size:11px; font-weight:700; color:#5b9e62;" title="' + (sg.likely === 'contains' ? 'Name contains the match, within 100 m, no look-alike nearby' : sg.likely === 'address' ? 'No location in the file — matched by name and address' : 'Exact name, the only one within 500 m') + ' — Review & pin pins it">· likely · ' + (sg.likely === 'contains' ? 'contains' : sg.likely === 'address' ? escapeHtml(sg.why || 'by address') : sg.likely === 'area' ? 'large area' : sg.cell ? 'only one with this name · ≈ list link' : 'only one in 500 m') + (typeof sg.m === 'number' && !sg.cell ? ' · ' + sg.m + ' m' : '') + '</span>'; else if (sg.probable) h += ' <span class="dim" style="font-size:11px;" title="Several candidates — tap the right name in Pick by name, or pick on the map">· pick by name' + (sg.alts && sg.alts.length ? ' · ' + sg.alts.length + ' look-alike' + (sg.alts.length === 1 ? '' : 's') : '') + (tkIsCellRow(p) ? ' · ≈ list link' : '') + '</span>'; else h += ' <span class="dim" style="font-size:11px;" title="One suggestion — confirm from its card, or in Pick by name">· suggested · pick by name</span>'; } } /* r86-2: حالة كل صف في الصندوق */ if (p.hold === 'guidelines') h += ' <span style="font-size:11px; font-weight:700; color:#b3261e;" title="Outside the content guidelines — not sorted; remove it from the box">· outside guidelines</span>'; if (p.dup) h += ' <span class="dim" style="font-size:11px; font-weight:700;" title="Same place as one you already have pinned (same map identity)">· already pinned</span>'; if (!(p.geo && typeof p.geo.lat === 'number') && p.hold !== 'guidelines' && !p.dup) h += ' <button type="button" class="chip" style="padding:1px 8px; font-size:11px;" onclick="event.stopPropagation(); tkPastePin(\'' + attrStr(plSugKey(p)) + '\')" title="Open it in Google Maps (Maps ↗), Share → copy link, come back and tap">📋 Paste &amp; pin</button>'; /* r86-8 (البند ٤): من البداية لكل مكان بلا دبوس */ if (p.autoCat && !p.hold) h += ' <span class="dim" style="font-size:11px;">· ' + escapeHtml(String(p.autoCat).replace(/_/g, ' ')) + '</span>'; return h; } /* وسوم نصًّا بحجم السطر — لا شرائح (ملاحظة المالك على الشجرة ١٥:٤٠) */
/* ── الإضافة اليدوية: مرشَّح أكيد بفئة ممنوعة → لا دبوس ولا حفظ معه؛ Skip = «ليس هذا المكان» يبقى متاحًا · تحذير بالاسم بلا منع ── */
function tkGeoBanned(res){ return !!(res && res.auto && tkCatBanned(res.auto.cat)); }
function tkGuidelineMsg(){ return 'This looks like a place outside MyPickz’s content guidelines (bars, nightlife, alcohol, hookah, gambling) — it can’t be pinned or saved as this match. If it’s a different place, use Skip and it stays unpinned.'; }
